   252  M3Result  ParseSection_Start  (IM3Module io_module, bytes_t i_bytes, cbytes_t i_end)
   253  {
   254      M3Result result = m3Err_none;
   255
   256      u32 startFuncIndex;
   257  _   (ReadLEB_u32 (& startFuncIndex, & i_bytes, i_end));                               m3log (parse, "** Start Function: %d", startFuncIndex);
   258
   259      if (startFuncIndex < io_module->numFunctions)
   260      {
   261          io_module->startFunction = startFuncIndex;
   262      }
   263      else result = "start function index out of bounds";
   264
   265      _catch: return result;
   266  }
