   269  M3Result  Parse_InitExpr  (M3Module * io_module, bytes_t * io_bytes, cbytes_t i_end)
   270  {
   271      M3Result result = m3Err_none;
   272
   273      // this doesn't generate code pages. just walks the wasm bytecode to find the end
   274
   275  #if defined(d_m3PreferStaticAlloc)
   276      static M3Compilation compilation;
   277  #else
   278      M3Compilation compilation;
   279  #endif
   280      compilation = (M3Compilation){ NULL, io_module, * io_bytes, i_end };
   281
   282      result = Compile_BlockStatements (& compilation);
   283
   284      * io_bytes = compilation.wasm;
   285
   286      return result;
   287  }
