   372  M3Result  ParseSection_Data  (M3Module * io_module, bytes_t i_bytes, cbytes_t i_end)
   373  {
   374      M3Result result = m3Err_none;
   375
   376      u32 numDataSegments;
   377  _   (ReadLEB_u32 (& numDataSegments, & i_bytes, i_end));                            m3log (parse, "** Data [%d]", numDataSegments);
   378
   379      io_module->dataSegments = m3_AllocArray (M3DataSegment, numDataSegments);
   380      _throwifnull(io_module->dataSegments);
   381      io_module->numDataSegments = numDataSegments;
   382
   383      for (u32 i = 0; i < numDataSegments; ++i)
   384      {
   385          M3DataSegment * segment = & io_module->dataSegments [i];
   386
   387  _       (ReadLEB_u32 (& segment->memoryRegion, & i_bytes, i_end));
   388
   389          segment->initExpr = i_bytes;
   390  _       (Parse_InitExpr (io_module, & i_bytes, i_end));
   391          segment->initExprSize = (u32) (i_bytes - segment->initExpr);
   392
   393          _throwif (m3Err_wasmMissingInitExpr, segment->initExprSize <= 1);
   394
   395  _       (ReadLEB_u32 (& segment->size, & i_bytes, i_end));
   396          segment->data = i_bytes;                                                    m3log (parse, "    segment [%u]  memory: %u;  expr-size: %d;  size: %d",
   397                                                                                         i, segment->memoryRegion, segment->initExprSize, segment->size);
   398          i_bytes += segment->size;
   399      }
   400
   401      _catch:
   402
   403      return result;
   404  }
