   424  M3Result  ParseSection_Global  (M3Module * io_module, bytes_t i_bytes, cbytes_t i_end)
   425  {
   426      M3Result result = m3Err_none;
   427
   428      u32 numGlobals;
   429  _   (ReadLEB_u32 (& numGlobals, & i_bytes, i_end));                                 m3log (parse, "** Global [%d]", numGlobals);
   430
   431      for (u32 i = 0; i < numGlobals; ++i)
   432      {
   433          i8 waType;
   434          u8 type, isMutable;
   435
   436  _       (ReadLEB_i7 (& waType, & i_bytes, i_end));
   437  _       (NormalizeType (& type, waType));
   438  _       (ReadLEB_u7 (& isMutable, & i_bytes, i_end));                                 m3log (parse, "    global: [%d] %s mutable: %d", i, c_waTypes [type],   (u32) isMutable);
   439
   440          IM3Global global;
   441  _       (Module_AddGlobal (io_module, & global, type, isMutable, false /* isImport */));
   442
   443          global->initExpr = i_bytes;
   444  _       (Parse_InitExpr (io_module, & i_bytes, i_end));
   445          global->initExprSize = (u32) (i_bytes - global->initExpr);
   446
   447          _throwif (m3Err_wasmMissingInitExpr, global->initExprSize <= 1);
   448      }
   449
   450      _catch: return result;
   451  }
